package dev.industrialtechnology.railway;
import net.minecraft.block.Block;import net.minecraft.item.*;import net.minecraft.init.*;import cpw.mods.fml.common.registry.*;import dev.industrialtechnology.core.*;import net.minecraftforge.oredict.*;
public final class RailwayRegistry {
 public static final Block[] solar=new Block[5],stations=new Block[3];public static Block anchor;public static final Item[] trackItems=new Item[6],stockItems=new Item[6];public static Item coupler,bogie,chassis,motor,boiler;
 public static void register(){for(int i=0;i<5;i++){solar[i]=new dev.industrialtechnology.solar.BlockSolar(i);GameRegistry.registerBlock(solar[i],"solar_"+i);}GameRegistry.registerTileEntity(dev.industrialtechnology.solar.TileSolar.class,"industrialtech:solar_panel");anchor=new BlockRailAnchor();GameRegistry.registerBlock(anchor,"rail_anchor");GameRegistry.registerTileEntity(TileTrack.class,"industrialtech:rail_segment");for(int i=0;i<6;i++){trackItems[i]=new ItemTrack(i);GameRegistry.registerItem(trackItems[i],"track_"+i);stockItems[i]=new ItemRollingStock(StockType.safe(i));GameRegistry.registerItem(stockItems[i],"stock_"+i);}for(int i=0;i<3;i++){stations[i]=new BlockRailStation(i);GameRegistry.registerBlock(stations[i],"rail_station_"+i);}GameRegistry.registerTileEntity(TileRailStation.class,"industrialtech:rail_station");coupler=part("rail_coupler");bogie=part("rail_bogie");chassis=part("rail_chassis");motor=part("traction_motor");boiler=part("steam_boiler");EntityRegistry.registerModEntity(EntityRollingStock.class,"industrial_rolling_stock",1,IndustrialTechnology.instance,192,2,true);}
 private static Item part(String name){Item i=new Item().setUnlocalizedName("industrialtech."+name).setTextureName("industrialtech:"+name).setCreativeTab(ModRegistry.TAB);GameRegistry.registerItem(i,name);return i;}
 private static void recipe(ItemStack result,Object... data){GameRegistry.addRecipe(new ShapedOreRecipe(result,data));}
 public static void recipes(){Object steel=OreDictionary.getOres("ingotSteel").isEmpty()?Items.iron_ingot:"ingotSteel";recipe(new ItemStack(solar[0]),"GGG","CRC","III",'G',Blocks.glass,'C',ModRegistry.circuit,'R',Blocks.redstone_block,'I',steel);for(int i=1;i<5;i++)recipe(new ItemStack(solar[i]),"DPD","PCP","DPD",'D',i<2?Items.gold_ingot:i<3?Items.diamond:i<4?Blocks.diamond_block:Items.nether_star,'P',solar[i-1],'C',i<3?ModRegistry.circuit:ModRegistry.capacitorBank);
 recipe(new ItemStack(coupler,2)," I ","IGI"," I ",'I',steel,'G',ModRegistry.gear);recipe(new ItemStack(bogie),"GIG","III","GIG",'I',Blocks.iron_block,'G',ModRegistry.gear);recipe(new ItemStack(chassis),"III","BCB","III",'I',Blocks.iron_block,'B',bogie,'C',coupler);recipe(new ItemStack(motor),"RGR","ICI","RGR",'R',Blocks.redstone_block,'G',Items.gold_ingot,'I',steel,'C',ModRegistry.circuit);recipe(new ItemStack(boiler),"III","IFI","III",'I',Blocks.iron_block,'F',Blocks.furnace);
 recipe(new ItemStack(stockItems[0]),"BBB","GFG","CTC",'B',boiler,'G',ModRegistry.gear,'F',Blocks.furnace,'C',chassis,'T',Blocks.chest);recipe(new ItemStack(stockItems[1]),"III","MCM","BKB",'I',Blocks.iron_block,'M',motor,'C',ModRegistry.circuit,'B',chassis,'K',ModRegistry.capacitorBank);recipe(new ItemStack(stockItems[2]),"DGD","MCM","BLB",'D',Items.diamond,'G',Blocks.glass,'M',motor,'C',ModRegistry.circuit,'B',chassis,'L',stockItems[1]);recipe(new ItemStack(stockItems[3]),"DMD","LKL","CMC",'D',Blocks.diamond_block,'M',motor,'L',stockItems[1],'K',ModRegistry.capacitorBank,'C',chassis);recipe(new ItemStack(stockItems[4]),"III","HTH","BCB",'I',steel,'H',Blocks.iron_block,'T',Blocks.chest,'B',bogie,'C',chassis);recipe(new ItemStack(stockItems[5]),"GGG","IWI","BCB",'G',Blocks.glass,'I',steel,'W',Blocks.wool,'B',bogie,'C',chassis);
 for(int i=0;i<6;i++)recipe(new ItemStack(trackItems[i],4),"ISI","ISI","ISI",'I',steel,'S',i==3?Blocks.stone_stairs:i==4?Items.redstone:i==5?Blocks.redstone_block:Blocks.planks);recipe(new ItemStack(stations[0]),"IMI","CKC","III",'I',steel,'M',motor,'C',ModRegistry.circuit,'K',ModRegistry.capacitorBank);for(int i=1;i<3;i++)recipe(new ItemStack(stations[i]),"IHI","CMC","IRI",'I',steel,'H',Blocks.hopper,'C',Blocks.chest,'M',motor,'R',i==1?Items.redstone:Items.gold_ingot);}
}
